"""Package whose loader accepts a custom importer shadowing importlib."""

import importlib

backend = importlib.import_module(name="shadow_pkg.backend")


def load_via(importlib):
    # The parameter shadows the module-level import: this call must dispatch to
    # the custom object's own import_module method, not to the bundled module.
    return importlib.import_module(name="shadow_pkg.backend")


def real_kind():
    return backend.KIND
